<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Learn_english_rpg_reports extends MY_Controller
{
 public function index(){$this->require_permission('learn_english_rpg.index','view');$stats=['players'=>(int)$this->db->count_all('learn_english_rpg_profiles'),'attempts'=>(int)$this->db->count_all('learn_english_rpg_activity'),'completed'=>(int)$this->db->where('is_completed',1)->count_all_results('learn_english_rpg_progress'),'words'=>(int)$this->db->count_all('learn_english_rpg_word_mastery')];$hard=$this->db->select('word,meaning,SUM(wrong_count) wrong,SUM(correct_count) correct,AVG(mastery_score) mastery',false)->group_by('word,meaning')->order_by('mastery')->limit(30)->get('learn_english_rpg_word_mastery')->result_array();$players=$this->db->select('p.*,u.full_name,(SELECT COUNT(*) FROM learn_english_rpg_progress x WHERE x.user_id=p.user_id AND x.is_completed=1) chapters',false)->from('learn_english_rpg_profiles p')->join('auth_user u','u.id=p.user_id','left')->order_by('p.total_correct','DESC')->limit(100)->get()->result_array();$this->render('learn/english_rpg/report_page',['title'=>'Analitik English RPG','active_menu'=>'learn_english_rpg','stats'=>$stats,'hard_words'=>$hard,'players'=>$players]);}
}
